    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);

        (bool ok, bytes memory ret) = caddress.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[0], v)
        );
        require(ok);

        bool reverted;
        bool retVal;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            retVal = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && retVal);
    }
}

